@startuml

class Traveller {
  + name : string
  + companyName : string
  + address : string
  + billingInformation : string
  + reliabilityRating : float
}

class TravelPreference {
  + description : string
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : string
  + minimumRating : int
  + maxCostPerNight : float
}

class Booking {
  + bookingIdentifier : string
  + price : float
  + status : string
  + cancellationDeadline : date
}

enum BookingType {
  PRELIMINARY
  PRELIMINARY_FINALIZED
  COMPLETED
}

enum PaymentMethod {
  PRE_PAID
  PAID_AT_HOTEL
}

class CreditCardInfo {
  + cardNumber : string
}

class Hotel {
  + name : string
  + address : string
  + rating : int
}

class HotelChain {
  + name : string
}

class SpecialOffer {
  + price : float
  + offerTime : datetime
}

class RoomType {
  + typeName : string
}

class Availability {
  + isFullyBooked : boolean
}

class City {
  + name : string
}

Traveller "1" *-- "0..*" TravelPreference
Traveller "1" -- "0..*" Booking
Traveller "1" -- "0..*" CreditCardInfo
Traveller "1" -- "0..*" SpecialOffer : receives

Booking "1" -- "1" BookingType
Booking "1" -- "0..1" PaymentMethod
Booking "1" -- "1" Hotel
Booking "1" -- "1" City

Hotel "0..*" -- "0..1" HotelChain
Hotel "1" -- "1" City
Hotel "1" -- "*" Availability
Availability "*" -- "1" RoomType
Hotel "1" -- "*" SpecialOffer : provides

Booking "1" -- "0..*" SpecialOffer : can switch to

@enduml

